-- =====================================================================
-- V3 : 논리 모델 슈퍼타입·서브타입 (M-6 후속 5차, 2026-11-20 — docs/completed/logical-subtype.md)
-- 슈퍼타입 엔터티는 서브타입 그룹(TB_LGCL_SBTYP_GROUP)을 여러 개 가질 수 있고, 그룹은 서브타입(TB_LGCL_SBTYP) 2개 이상으로 이루어진다 (최소 2개는 서비스가 검사).
-- 단일 상속 : 엔터티 하나는 서브타입 행 하나에만 (UX_LGCL_SBTYP_01) — 직접 슈퍼타입 하나, 그룹 하나. 최대 깊이(루트 = 1단계, 3단계까지)·자기 상속·순환·같은 모델·
--   같은 프로젝트·그룹명 중복(같은 슈퍼타입 안, 대소문자 무시)은 논리 모델 행을 잠근 뒤 서비스가 검사한다 (주제 영역과 같은 분담).
-- 분류 정책은 그룹마다 필수값이고 DB 기본값이 없다 (사용자가 고른다) : 중복 가능 여부(DPCN_PSBLTY_YN — Y = Overlapping, N = Disjoint),
--   완전 여부(TOTL_YN — Y = Total, N = Partial). 분류 속성(CLSF_ATRB_SN, 선택)은 슈퍼타입의 유효 속성(직접 또는 조상에서 상속)의 원본 속성 ID, 분류 값(CLSF_VL)은 메타데이터 문자열이다.
-- 상속 속성·식별자는 저장하지 않는다 (원본 엔터티의 행을 조회 때 계산한다). 상속은 엔터티 행을 바꾸지 않는다 (수정 일시·승인 상태 그대로).
-- 기존 논리 모델·엔터티에는 서브타입 그룹을 만들지 않는다. 예제(프로젝트 0)에도 그룹 데이터는 만들지 않는다.
-- 예제(프로젝트 0)에 새 테이블을 단어·용어 → 물리 → 논리 → 매핑 → 관계(+ 속성 짝) → 인덱스 → 업무 설명 순서로 넣는다 (V2 와 같은 규칙).
-- 단어 (2026-11-20 사용자 결정 D-49) : 슈퍼타입(SPRTYP)·서브타입(SBTYP)·완전(TOTL)은 Lexorma 기관 표준단어 (공통표준단어에 없다 — static/excel/dataPortal.xlsx 로 확인).
--   그룹(GROUP)·분류(CLSF)·값(VL)·속성(ATRB)은 예제 사전에 이미 있다. 중복(DPCN)·가능(PSBLTY)은 공통표준단어, 중복_가능_여부(DPCN_PSBLTY_YN)는 공통표준용어 그대로
--   (같은 날 사용자 결정 — 처음 정한 DPLCT_ALWNC_YN 은 공통표준 중복 = DPCN 과 달라 바꿨다). 도메인은 컬럼이 BOOLEAN 이라 자체 도메인 여부B (필수_여부 와 같은 규칙).
-- =====================================================================

create sequence SQ_LGCL_SBTYP_GROUP start with 1 increment by 50;
create table TB_LGCL_SBTYP_GROUP (
    LGCL_SBTYP_GROUP_SN bigint not null,
    PRJ_SN bigint not null,
    LGCL_MDL_SN bigint not null,
    SPRTYP_ENTT_SN bigint not null,
    SBTYP_GROUP_NM varchar(255) not null,
    SBTYP_GROUP_EXPLN varchar(1000),
    DPCN_PSBLTY_YN boolean not null,
    TOTL_YN boolean not null,
    CLSF_ATRB_SN bigint,
    SORT_ORD integer not null,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_LGCL_SBTYP_GROUP primary key (LGCL_SBTYP_GROUP_SN)
);
create sequence SQ_LGCL_SBTYP start with 1 increment by 50;
create table TB_LGCL_SBTYP (
    LGCL_SBTYP_SN bigint not null,
    PRJ_SN bigint not null,
    LGCL_MDL_SN bigint not null,
    LGCL_SBTYP_GROUP_SN bigint not null,
    SBTYP_ENTT_SN bigint not null,
    CLSF_VL varchar(255),
    SORT_ORD integer not null,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_LGCL_SBTYP primary key (LGCL_SBTYP_SN)
);
create unique index UX_LGCL_SBTYP_GROUP_01 on TB_LGCL_SBTYP_GROUP (SPRTYP_ENTT_SN, SBTYP_GROUP_NM);
create index IX_LGCL_SBTYP_GROUP_01 on TB_LGCL_SBTYP_GROUP (LGCL_MDL_SN);
create index IX_LGCL_SBTYP_GROUP_02 on TB_LGCL_SBTYP_GROUP (CLSF_ATRB_SN);
create unique index UX_LGCL_SBTYP_01 on TB_LGCL_SBTYP (SBTYP_ENTT_SN);
create index IX_LGCL_SBTYP_01 on TB_LGCL_SBTYP (LGCL_SBTYP_GROUP_SN, SORT_ORD);
create index IX_LGCL_SBTYP_02 on TB_LGCL_SBTYP (LGCL_MDL_SN);
alter table TB_LGCL_SBTYP_GROUP add constraint FK_LGCL_SBTYP_GROUP_01 foreign key (LGCL_MDL_SN) references TB_LGCL_MDL;
alter table TB_LGCL_SBTYP_GROUP add constraint FK_LGCL_SBTYP_GROUP_02 foreign key (SPRTYP_ENTT_SN) references TB_LGCL_ENTT;
alter table TB_LGCL_SBTYP_GROUP add constraint FK_LGCL_SBTYP_GROUP_03 foreign key (CLSF_ATRB_SN) references TB_LGCL_ATRB;
alter table TB_LGCL_SBTYP add constraint FK_LGCL_SBTYP_01 foreign key (LGCL_SBTYP_GROUP_SN) references TB_LGCL_SBTYP_GROUP;
alter table TB_LGCL_SBTYP add constraint FK_LGCL_SBTYP_02 foreign key (SBTYP_ENTT_SN) references TB_LGCL_ENTT;
alter table TB_LGCL_SBTYP add constraint FK_LGCL_SBTYP_03 foreign key (LGCL_MDL_SN) references TB_LGCL_MDL;

comment on table TB_LGCL_SBTYP_GROUP is '논리 서브타입 그룹';
comment on column TB_LGCL_SBTYP_GROUP.LGCL_SBTYP_GROUP_SN is '논리 서브타입 그룹 일련번호';
comment on column TB_LGCL_SBTYP_GROUP.PRJ_SN is '프로젝트 일련번호';
comment on column TB_LGCL_SBTYP_GROUP.LGCL_MDL_SN is '논리 모델 일련번호';
comment on column TB_LGCL_SBTYP_GROUP.SPRTYP_ENTT_SN is '슈퍼타입 엔터티 일련번호';
comment on column TB_LGCL_SBTYP_GROUP.SBTYP_GROUP_NM is '서브타입 그룹 명';
comment on column TB_LGCL_SBTYP_GROUP.SBTYP_GROUP_EXPLN is '서브타입 그룹 설명';
comment on column TB_LGCL_SBTYP_GROUP.DPCN_PSBLTY_YN is '중복 가능 여부';
comment on column TB_LGCL_SBTYP_GROUP.TOTL_YN is '완전 여부';
comment on column TB_LGCL_SBTYP_GROUP.CLSF_ATRB_SN is '분류 속성 일련번호';
comment on column TB_LGCL_SBTYP_GROUP.SORT_ORD is '정렬 순서';
comment on column TB_LGCL_SBTYP_GROUP.REG_DT is '등록 일시';
comment on column TB_LGCL_SBTYP_GROUP.MDFCN_DT is '수정 일시';
comment on column TB_LGCL_SBTYP_GROUP.RGTR_ID is '등록자 아이디';
comment on column TB_LGCL_SBTYP_GROUP.MDFR_ID is '수정자 아이디';
comment on table TB_LGCL_SBTYP is '논리 서브타입';
comment on column TB_LGCL_SBTYP.LGCL_SBTYP_SN is '논리 서브타입 일련번호';
comment on column TB_LGCL_SBTYP.PRJ_SN is '프로젝트 일련번호';
comment on column TB_LGCL_SBTYP.LGCL_MDL_SN is '논리 모델 일련번호';
comment on column TB_LGCL_SBTYP.LGCL_SBTYP_GROUP_SN is '논리 서브타입 그룹 일련번호';
comment on column TB_LGCL_SBTYP.SBTYP_ENTT_SN is '서브타입 엔터티 일련번호';
comment on column TB_LGCL_SBTYP.CLSF_VL is '분류 값';
comment on column TB_LGCL_SBTYP.SORT_ORD is '정렬 순서';
comment on column TB_LGCL_SBTYP.REG_DT is '등록 일시';
comment on column TB_LGCL_SBTYP.MDFCN_DT is '수정 일시';
comment on column TB_LGCL_SBTYP.RGTR_ID is '등록자 아이디';
comment on column TB_LGCL_SBTYP.MDFR_ID is '수정자 아이디';

-- ---------- 예제 : 데이터 사전 (새 단어 5개, 새 용어 10개 — 나머지 용어는 있다) ----------
-- ---------- 예제 : 물리 모델 TB_LGCL_SBTYP_GROUP ----------
-- ---------- 예제 : 논리 모델 논리 서브타입 그룹 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 논리 서브타입 그룹 ----------
-- ---------- 예제 : 물리 모델 TB_LGCL_SBTYP ----------
-- ---------- 예제 : 논리 모델 논리 서브타입 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 논리 서브타입 ----------
-- ---------- 예제 : 관계 (V3 의 FK 그대로) + 논리 관계 + 그 논리 관계의 속성 짝 (FK 컬럼 그대로) ----------
-- ---------- 예제 : 인덱스 (V3 의 create index 그대로) ----------
-- ---------- 예제 : 업무 설명 ----------
update TB_TBL set TASK_EXPLN = '슈퍼타입 하나를 하나의 기준으로 나눈 서브타입 묶음. 슈퍼타입은 서로 다른 기준의 그룹을 여러 개 가질 수 있다. 중복 가능(Overlapping/Disjoint)·완전(Total/Partial)은 그룹 안에서만 뜻을 가지며 업무 데이터로 강제하지 않는 모델링 정보다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '서브타입 그룹을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'LGCL_SBTYP_GROUP_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이 행이 속한 프로젝트. 조회와 변경은 로그인할 때 고른 프로젝트 안으로 제한되며, 프로젝트를 지우면 함께 지운다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '그룹이 속한 논리 모델. 슈퍼타입과 서브타입은 모두 이 모델의 엔터티다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'LGCL_MDL_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '공통 속성·주 식별자를 정의하는 슈퍼타입 엔터티.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'SPRTYP_ENTT_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '그룹 이름. 같은 슈퍼타입 안에서 대소문자 구분 없이 하나뿐이다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'SBTYP_GROUP_NM' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '그룹의 분류 기준 설명. 실행하는 조건식이 아니다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'SBTYP_GROUP_EXPLN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '같은 인스턴스가 그룹의 여러 서브타입에 함께 속할 수 있는지 (참 = Overlapping, 거짓 = Disjoint). 기본값 없이 사용자가 고른다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'DPCN_PSBLTY_YN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '모든 슈퍼타입 인스턴스가 그룹의 서브타입 중 하나 이상에 속해야 하는지 (참 = Total, 거짓 = Partial). 기본값 없이 사용자가 고른다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'TOTL_YN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '서브타입을 나누는 슈퍼타입의 속성 (선택). 슈퍼타입에 직접 있거나 조상에서 상속한 원본 속성이다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'CLSF_ATRB_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '같은 슈퍼타입 안의 그룹 표시 순서.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'SORT_ORD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP_GROUP' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;
update TB_TBL set TASK_EXPLN = '서브타입 그룹에 속한 엔터티. 서브타입은 슈퍼타입의 속성·주 식별자를 복제하지 않고 상속해 보여 준다. 엔터티 하나는 하나의 그룹에만 서브타입으로 속한다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '서브타입 행을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP' and COL_NM = 'LGCL_SBTYP_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이 행이 속한 프로젝트. 조회와 변경은 로그인할 때 고른 프로젝트 안으로 제한되며, 프로젝트를 지우면 함께 지운다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '그룹·엔터티의 논리 모델 (조회 조건용 — 둘의 모델과 같다).' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP' and COL_NM = 'LGCL_MDL_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이 서브타입이 속한 그룹.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP' and COL_NM = 'LGCL_SBTYP_GROUP_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '서브타입 엔터티. 엔터티 하나는 서브타입 행 하나에만 있다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP' and COL_NM = 'SBTYP_ENTT_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '그룹의 분류 속성이 이 서브타입을 가리키는 값 (선택, 메타데이터). Disjoint 그룹 안에서는 겹치지 않는다.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP' and COL_NM = 'CLSF_VL' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '그룹 안의 서브타입 표시 순서.' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP' and COL_NM = 'SORT_ORD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_LGCL_SBTYP' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;
